set-variable.value:
@{
			var headers = context.Request.Headers;
			var names = headers.Keys.Where(k => k.StartsWith("x-ai4ia-attempt", StringComparison.OrdinalIgnoreCase) || k.StartsWith("x-ai4ia-proxy-attempt", StringComparison.OrdinalIgnoreCase)).ToArray();
			if (names.Length == 0) { return 0; }
			if (names.Length != 2 || context.Subscription == null ||
				!headers.ContainsKey("x-ai4ia-attempt") || !headers.ContainsKey("x-ai4ia-proxy-attempt") ||
				headers["x-ai4ia-attempt"].Length != 1 || headers["x-ai4ia-proxy-attempt"].Length != 1 ||
				!headers.ContainsKey("x-LLMModel") || headers["x-LLMModel"].Length != 1) { return -1; }
			string value = headers["x-ai4ia-attempt"][0];
			string signature = headers["x-ai4ia-proxy-attempt"][0];
			var match = System.Text.RegularExpressions.Regex.Match(value, @"\Aai4ia-one-attempt-v1\.([0-9a-f]{32})\.([0-9a-f]{64})\z");
			if (!match.Success || !System.Text.RegularExpressions.Regex.IsMatch(signature, @"\A[0-9a-f]{64}\z") || context.Request.Method != "POST") { return -1; }
			byte[] body = context.Request.Body.As<byte[]>(preserveContent: true);
			if (body.Length > 1048576) { return -1; }
			string digest = BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(body)).Replace("-", "").ToLowerInvariant();
			if (digest != match.Groups[2].Value) { return -1; }
			string query = context.Request.OriginalUrl.QueryString;
			string path = context.Request.OriginalUrl.Path + (string.IsNullOrEmpty(query) ? "" : "?" + query.TrimStart('?'));
			string signed = value + "\nPOST\n" + path + "\n" + headers["x-LLMModel"][0];
			foreach (string key in new[] { context.Subscription.PrimaryKey, context.Subscription.SecondaryKey }) {
				if (string.IsNullOrEmpty(key)) { continue; }
				string expected = BitConverter.ToString(new System.Security.Cryptography.HMACSHA256(System.Text.Encoding.UTF8.GetBytes(key)).ComputeHash(System.Text.Encoding.UTF8.GetBytes(signed))).Replace("-", "").ToLowerInvariant();
				int difference = 0;
				for (int i = 0; i < expected.Length; i++) { difference |= expected[i] ^ signature[i]; }
				if (difference == 0) { return 1; }
			}
			return -1;
		}

@{
			string value = context.Request.Headers.GetValueOrDefault("x-ai4ia-attempt", "");
			return context.Variables.GetValueOrDefault<bool>("noReplay", false) ? value.Substring(0, value.LastIndexOf('.')) : "";
		}
